jQuery(document).ready(function($){"use strict";let now=new Date;const oneDay=864e5;let today=getDateRange(now);let report_affiliates={};let report_referrals={};let report_clicks={};let report_payout={};let general_affiliates_chart=null,payout_request_chart=null,clicks_event_chart=null,referrals_log_chart=null;if($(".affi-affiliate-reports-container").length){ajax_func({time_option:"today"},"affiliates")}if($(".affi-referrals-reports-container").length){ajax_func({time_option:"today"},"referrals")}if($(".affi-clicks-reports-container").length){ajax_func({time_option:"today"},"clicks")}if($(".affi-payout-reports-container").length){ajax_func({time_option:"today"},"payouts")}$(".affi-date-from").val(today);$(".affi-date-to").val(today);$(".affi-select-time-report").on("change",function(){let thisVal=$(this).val(),from_date=$(".affi-date-from"),to_date=$(".affi-date-to"),type=$(this).data("type");if(thisVal!=="custom"){$(".affi-custom-time-range").hide();switch($(this).val()){case"today":from_date.val(today);to_date.val(today);break;case"yesterday":let yesterday=new Date(Date.now()-oneDay);yesterday=getDateRange(yesterday);from_date.val(yesterday);to_date.val(yesterday);break;case"30days":let _30days=new Date(Date.now()-30*oneDay);_30days=getDateRange(_30days);from_date.val(_30days);to_date.val(today);break;case"90days":let _90days=new Date(Date.now()-90*oneDay);_90days=getDateRange(_90days);from_date.val(_90days);to_date.val(today);break;case"365days":let _365days=new Date(Date.now()-365*oneDay);_365days=getDateRange(_365days);from_date.val(_365days);to_date.val(today);break}switch(type){case"affiliates":ajax_func({time_option:$(this).val()},type);break;case"referrals":ajax_func({time_option:$(this).val()},type);break;case"clicks":ajax_func({time_option:$(this).val()},type);break;case"payouts":ajax_func({time_option:$(this).val()},type);break;default:}}else{$(".affi-custom-time-range").show()}});$(".affi-view-reports").on("click",function(){let type=$(this).data("type");$(".affi-select-time-report").val("custom");let data={from_date:new Date($(".affi-date-from").val()).getTime()/1e3,to_date:new Date($(".affi-date-to").val()).getTime()/1e3+86400-1};if(data.from_date<data.to_date){if(data.to_date-data.from_date<31*24*60*60){ajax_func(data,type)}else{alert("Time range more than 30 days. Please select again")}}else{alert("Please select start date less than end date")}});function ajax_func(data,type){$.ajax({url:affiParams.ajaxUrl,type:"POST",data:{nonce:affiParams.nonce,action:"affi_get_reports",report_type:type,data:data},success:function(result){drawChart(result,type);switch(type){case"referrals":report_referrals=result;ref_report(result);$(".affi-print-report-button.affi-print-report-referrals").removeClass("affi-loading");break;case"clicks":report_clicks=result;cl_report(result);$(".affi-print-report-button.affi-print-report-clicks").removeClass("affi-loading");break;case"payouts":report_payout=result;pay_report(result);$(".affi-print-report-button.affi-print-report-payouts").removeClass("affi-loading");break;default:report_affiliates=result;aff_report(result);$(".affi-print-report-button.affi-print-report-general").removeClass("affi-loading")}},error:function(result){},beforeSend:function(){switch(type){case"cashier":$(".affi-print-report-button.affi-print-report-cashier").addClass("affi-loading");break;case"payment":$(".affi-print-report-button.affi-print-report-payment").addClass("affi-loading");break;case"outlet":$(".affi-print-report-button.affi-print-report-outlet").addClass("affi-loading");break;default:$(".affi-print-report-button.affi-print-report-general").addClass("affi-loading")}},complete:function(){}})}let myChart=null;function drawChart(data,chart_type){let myChart=null,canvas_wrap="",ctx_wrap="",ctx="",ctx_aff_wrap="",ctx_aff="",ctx_click_wrap="",ctx_click="",ctx_ref_wrap="",ctx_ref="",ctx_payout_wrap="",ctx_payout="",referrals_data=data.ref,referrals_datasets=[],report_label=[],index=0;if(myChart!=null){myChart.destroy()}switch(chart_type){case"referrals":if(referrals_log_chart!=null){referrals_log_chart.destroy()}canvas_wrap=$(".affi-referrals-reports-container .affi-chart-container");canvas_wrap.html('<canvas id="referrals_log_chart"></canvas>');ctx_ref_wrap=document.getElementById("referrals_log_chart");ctx_ref=document.getElementById("referrals_log_chart").getContext("2d");$.each(referrals_data,function(key,val){let line_color=get_color(index);report_label=val.label;referrals_datasets.push({label:key==="total"?"Total Value":"Completed Order Value",borderColor:"rgb("+line_color[0]+", "+line_color[1]+", "+line_color[2]+")",backgroundColor:"rgba("+line_color[0]+", "+line_color[1]+", "+line_color[2]+", 0.05)",data:val.value,borderWidth:1,pointBackgroundColor:"rgb("+line_color[0]+", "+line_color[1]+", "+line_color[2]+")",pointBorderColor:"rgba(0, 0, 0, 0)"});index++});referrals_log_chart=new Chart(ctx_ref,{type:"line",data:{labels:report_label,datasets:referrals_datasets},options:{responsive:true,maintainAspectRatio:true,aspectRatio:4,scales:{x:{gridLines:{display:false}},y:{gridLines:{display:true},ticks:{beginAtZero:true},title:{display:true,text:affiParams.total_text+" ("+affiParams.currency+")",fontSize:16}}}}});break;case"clicks":if(clicks_event_chart!=null){clicks_event_chart.destroy()}canvas_wrap=$(".affi-clicks-reports-container .affi-chart-container");canvas_wrap.html('<canvas id="clicks_event_chart"></canvas>');ctx_click_wrap=document.getElementById("clicks_event_chart");ctx_click=document.getElementById("clicks_event_chart").getContext("2d");let clicks_data=data.visit,clicks_datasets=[];if(data.visit){ctx_click_wrap.style.display="inherit";clicks_event_chart=new Chart(ctx_click,{type:"line",data:{labels:data.visit.label,datasets:[{label:"Total Clicks",borderColor:"red",backgroundColor:"rgba(255, 0, 0, 0.05)",data:data.visit.value,borderWidth:1,pointBackgroundColor:"red",pointBorderColor:"rgba(0, 0, 0, 0)"}]},options:{responsive:true,maintainAspectRatio:true,aspectRatio:4,scales:{x:{gridLines:{display:false},title:{display:true,text:affiParams.time_text,fontSize:16}},y:{gridLines:{display:true},ticks:{beginAtZero:true},title:{display:true,text:affiParams.total_text,fontSize:16}}}}})}break;case"payouts":if(payout_request_chart!=null){payout_request_chart.destroy()}canvas_wrap=$(".affi-payout-reports-container .affi-chart-container");canvas_wrap.html('<canvas id="payout_request_chart"></canvas>');ctx_payout_wrap=document.getElementById("payout_request_chart");ctx_payout=document.getElementById("payout_request_chart").getContext("2d");if(data.pay){ctx_payout_wrap.style.display="inherit";payout_request_chart=new Chart(ctx_payout,{type:"line",data:{labels:data.pay.label,datasets:[{label:"Payout Paid",borderColor:"red",backgroundColor:"rgba(255, 0, 0, 0.05)",data:data.pay.value,borderWidth:1,pointBackgroundColor:"red",pointBorderColor:"rgba(0, 0, 0, 0)"}]},options:{responsive:true,maintainAspectRatio:true,aspectRatio:4,scales:{x:{gridLines:{display:false}},y:{gridLines:{display:true},ticks:{beginAtZero:true},title:{display:true,text:affiParams.total_text+" ("+affiParams.currency+")",fontSize:16}}}}})}else{ctx_payout_wrap.style.display="none"}break;default:if(general_affiliates_chart!=null){general_affiliates_chart.destroy()}canvas_wrap=$(".affi-general-reports-container.affi-chart-container");canvas_wrap.html('<canvas id="general_affiliates_chart"></canvas>');ctx_aff_wrap=document.getElementById("general_affiliates_chart");ctx_aff=document.getElementById("general_affiliates_chart").getContext("2d");if(data.aff){$(ctx_aff_wrap).html("");ctx_aff_wrap.style.display="inherit";general_affiliates_chart=new Chart(ctx_aff,{type:"line",data:{labels:data.aff.label,datasets:[{label:"New affiliates",borderColor:"red",backgroundColor:"rgba(255, 0, 0, 0.05)",data:data.aff.value,borderWidth:1,pointBackgroundColor:"red",pointBorderColor:"rgba(0, 0, 0, 0)"}]},options:{responsive:true,maintainAspectRatio:true,aspectRatio:4,scales:{x:{gridLines:{display:false},title:{display:true,text:affiParams.time_text,fontSize:16}},y:{gridLines:{display:true},ticks:{beginAtZero:true},title:{display:true,text:affiParams.total_text,fontSize:16}}}}})}else{ctx_aff_wrap.style.display="none"}}}function getDateRange(obj){return obj.getFullYear()+"-"+("0"+(obj.getMonth()+1)).slice(-2)+"-"+("0"+obj.getDate()).slice(-2)}function aff_report(data){let highScore="";if(data.earn.name!==""&&data.earn.val!==""){highScore=`<span>${data.earn.name}</span><span>: ${data.earn.val+" ("+affiParams.currency+")"}</span>`}let html=`<div class="affi-report-cell"><h5>Total affiliates</h5><div>${data.total}</div></div>
            <div class="affi-report-cell"><h5>New Affiliates</h5><div>${data.new}</div></div>
            <div class="affi-report-cell"><h5>Top Earning Affiliate</h5>${highScore}</div>
<!--            <div class="affi-report-cell"><h5>Highest Converting Affiliate</h5><div>Messenger sent: ${data.messenger_sent}</div><div></div><div>Clicked ratio: ${clicked_ratio(data.messenger_clicked,data.messenger_sent)}%</div>-->`;$(".affi-general-reports-group").html(html)}function ref_report(data){let html=`<div class="affi-report-cell"><h5>Total Referrals</h5><div>${data.count}</div></div>
            <div class="affi-report-cell"><h5>Total Affiliate Value</h5><div>${data.total+" ("+affiParams.currency+")"}</div></div>
            <div class="affi-report-cell"><h5>Total Affiliate Earning</h5><div>${data.earn+" ("+affiParams.currency+")"}</div></div>
            <div class="affi-report-cell"><h5>Highest Affiliate User</h5><div>${data.aff}</div></div>`;$(".affi-general-reports-group").html(html)}function cl_report(data){let html=`<div class="affi-report-cell"><h5>Total Visits</h5><div>${data.total}</div></div>
            <div class="affi-report-cell"><h5>Most Visit URL</h5><div>${data.url}</div></div>`;$(".affi-general-reports-group").html(html)}function pay_report(data){let html=`<div class="affi-report-cell"><h5>Payout Paid</h5><div>${data.total+" ("+affiParams.currency+")"}</div></div>
<!--            <div class="affi-report-cell"><h5>Earnings Generated</h5><div>${data.pd_total}</div></div>-->
<!--            <div class="affi-report-cell"><h5>Request payouts Count</h5><div>${data.rq_total}</div></div>-->
            <div class="affi-report-cell"><h5>Payouts Count</h5><div>${data.count}</div></div>`;$(".affi-general-reports-group").html(html)}function clicked_ratio(clicked,total){let clicked_ratio=0;if(parseInt(total)){clicked_ratio=clicked/total*100}return clicked_ratio.toFixed(1)}function get_color(index){let pattern=[[255,0,0],[0,255,0],[0,0,255],[255,255,0],[255,0,255],[255,255,0],[0,255,255],[0,255,255],[255,0,255],[100,100,100],[200,200,200]];if(pattern[index]){return pattern[index]}else{let $red=Math.floor(Math.random()*255),$green=Math.floor(Math.random()*255),$blue=Math.floor(Math.random()*255);return[$red,$green,$blue]}}});